def dehydrate_timedelta(value):
    """Dehydrate a timedelta into a numeric representation (total seconds)."""
    if value is None:
        return None
    return value.total_seconds()

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: A datetime.time instance or None
    :type value: datetime.time
    :return: ISO 8601 formatted string or None
    """
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        return value.isoformat()
    raise TypeError(f"Expected a time-like object, got {type(value).__name__}")

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point
    :return: tuple of coordinates
    """
    if value is None:
        return None
    try:
        # Fetch x and y attributes
        coords = [getattr(value, 'x'), getattr(value, 'y')]
        # Include z if present
        if hasattr(value, 'z'):
            coords.append(getattr(value, 'z'))
        return tuple(coords)
    except AttributeError as exc:
        raise TypeError("Provided value does not appear to be a Point-like object") from exc

