@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Ensure the class has a mapping of handlers
        if not hasattr(cls, "_HANDLERS"):
            # If the mapping does not exist, create an empty dict
            # This can be overridden by subclasses
            cls._HANDLERS = {}

        # Validate the provided protocol_version
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, not {type(protocol_version).__name__}"
                )
            if not all(isinstance(v, int) for v in protocol_version):
                raise TypeError(
                    "Each element in protocol_version tuple must be an int"
                )
            # Return either the single handler or an empty dict
            if protocol_version in cls._HANDLERS:
                return {protocol_version: cls._HANDLERS[protocol_version]}
            else:
                return {}

        # If no specific version asked for, return all handlers
        # We return a shallow copy to prevent accidental mutation.
        return dict(cls._HANDLERS)

def values(self, *keys):
        """
        Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        # If no keys are supplied, return all values
        if not keys:
            return list(self._data.values())

        # Gather the values for the requested keys/indexes
        result = []
        all_keys = list(self._data.keys())

        for key in keys:
            if isinstance(key, int):
                # Treat integer key as an index
                try:
                    key = all_keys[key]
                except IndexError:
                    # Ignore out-of-range indexes
                    continue

            if key in self._data:
                result.append(self._data[key])

        return result

def data(self, *keys):
    """Return the keys and values of this record as a dictionary.

    If `keys` is empty, return all fields. Each argument may be a
    field name (string) or an index (integer).  Field names that are
    not present in the record are included with a value of ``None``.
    Out-of-range indexes raise :class:`IndexError`.
    """
    # The record is expected to expose the field names and the
    # corresponding values as sequence objects ``_field_names`` and
    # ``_values``.  If those attributes are missing we fall back to
    # ``self.keys`` and ``self.values`` to be more tolerant of
    # different implementations.
    field_names = getattr(self, "_field_names", None)
    if field_names is None:
        try:
            field_names = getattr(self, "keys", [])
        except Exception:
            field_names = []

    values = getattr(self, "_values", None)
    if values is None:
        try:
            values = getattr(self, "values", [])
        except Exception:
            values = []

    if not keys:
        return dict(zip(field_names, values))

    result = {}
    for k in keys:
        if isinstance(k, int):
            # Handle integer index: raise if out of bounds.
            if k < 0 or k >= len(values):
                raise IndexError(f"index {k} out of range for record with {len(values)} fields")
            field = field_names[k]
            result[field] = values[k]
        else:
            # Handle key lookup.
            if k in field_names:
                idx = field_names.index(k)
                result[k] = values[idx]
            else:
                result[k] = None
    return result

def round_half_to_even(n):
    """
    Round a number to the nearest integer using the banker's rounding rule
    (round half to even). This matches Python's built‑in round behaviour.
    """
    return int(round(n))

def point_type(name, fields, srid_map):
    """
    Dynamically create a Point subclass.
    """
    # Prepare the attributes for the new class
    attrs = {}
    # Define an __init__ that initializes all specified fields and SRIDs
    def __init__(self, **kwargs):
        # Initialize fields with provided values or default to None
        for field_name in fields:
            setattr(self, field_name, kwargs.get(field_name, None))
        # Initialize SRID values
        for srid_key, srid_value in srid_map.items():
            setattr(self, f"srid_{srid_key}", srid_value)
    # Add the __init__ method to the class dictionary
    attrs['__init__'] = __init__
    # Create and return the new class type
    return type(name, (object,), attrs)

def deprecated(message):
    def decorator(func):
        from functools import wraps
        import warnings
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    def _extract_int(part: str):
        i = 0
        n = len(part)
        sign = ''
        if i < n and (part[i] == '-' or part[i] == '+'):
            sign = part[i]
            i += 1
        start = i
        while i < n and part[i].isdigit():
            i += 1
        if start < i:
            try:
                return int(sign + part[start:i])
            except:
                pass
        return None

    nums = []
    for part in s.strip().split('.'):
        val = _extract_int(part)
        if val is not None:
            nums.append(val)
    return tuple(nums)

