def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock is not None:
                lock.acquire()
            try:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
            finally:
                if lock is not None:
                    lock.release()
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Convert an exception into a readable string, optionally trimming
        stack depth and file path components.
        """
        def _shorten_path(path):
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                return os.sep.join(['...' ] + parts[-max_path_level:])
            return path

        lines = []

        # main exception traceback
        tb = e.__traceback__
        if tb:
            stack = traceback.extract_tb(tb)
            # limit stack depth
            for frame in stack[-max_level:]:
                file_path = _shorten_path(frame.filename)
                lines.append(f"  at {file_path}:{frame.lineno} in {frame.name}")
        lines.append(f"{type(e).__name__}: {e}")

        # chain of causes / context
        current = e.__cause__ or e.__context__
        while current:
            lines.append(f"Caused by {type(current).__name__}: {current}")
            current = current.__cause__ or current.__context__

        return "\n".join(lines)

