@classmethod
    def _reset_logging(cls):
        """
        Reset the logging configuration to its default state by removing all
        handlers from all existing loggers (including the root logger).
        This can be useful when running tests or restarting a component
        that may have accumulated log handlers.
        """
        import logging
        root = logging.getLogger()
        # Remove handlers from the root logger and close them
        for h in root.handlers[:]:
            root.removeHandler(h)
            try:
                h.close()
            except Exception:
                pass
        root.handlers = []
        root.setLevel(logging.WARNING)

        # Remove handlers from all named loggers
        for logger_name, logger in list(root.manager.loggerDict.items()):
            # logger may be a Logger or a LoggerProxy; ensure it's a Logger instance
            if isinstance(logger, logging.Logger):
                for h in logger.handlers[:]:
                    logger.removeHandler(h)
                    try:
                        h.close()
                    except Exception:
                        pass

        # Optional: ensure that future use of basicConfig or other setup
        # starts with a clean slate.  We avoid calling basicConfig here
        # to prevent an unintended default handler from being attached.

def _getTargetClass(self):
    """Return the implementation class name without the 'Py' or 'Fallback' suffix."""
    cls_name = self.__class__.__name__
    for suffix in ("Py", "Fallback"):
        if cls_name.endswith(suffix):
            return cls_name[: -len(suffix)]
    return cls_name

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if all:
        # Gather attribute names from this class and all bases
        seen = set()
        result = []
        for cls in self.__class__.__mro__:
            for name, attr in cls.__dict__.items():
                if name.startswith('_'):
                    continue
                if name == 'names':
                    continue
                if callable(attr):
                    continue
                if name not in seen:
                    seen.add(name)
                    result.append(name)
        return result
    else:
        # Only attributes defined directly on this class
        result = []
        for name, attr in self.__class__.__dict__.items():
            if name.startswith('_'):
                continue
            if name == 'names':
                continue
            if callable(attr):
                continue
            result.append(name)
        return result

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, (list, tuple)):
            # Recursively normalize nested sequences
            _normalizeargs(item, output)
        else:
            output.append(item)
    return output

def _should_attempt_c_optimizations():
    import os, sys
    # Avoid C optimizations on PyPy
    if hasattr(sys, 'pypy_version_info'):
        return False
    # Respect PURE_PYTHON environment variable
    pure_python = os.getenv("PURE_PYTHON")
    if pure_python is not None:
        if pure_python.lower() in {"1", "true", "yes", "on"}:
            return False
    return True

