def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context.
    self.current_context = {}

    # Preserve the existing number of bins if possible.
    num_bins = None
    if hasattr(self, "bins") and self.bins is not None:
        num_bins = len(self.bins)

    # Reinitialize bins based on how the histogram was originally configured.
    if hasattr(self, "initial_value") and self.initial_value is not None:
        if num_bins is None or num_bins == 0:
            # If we don't have a prior bin count, start with a single bin.
            self.bins = [self.initial_value]
        else:
            self.bins = [self.initial_value] * num_bins
    else:
        if hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            # No method to recreate bins; default to an empty list.
            self.bins = []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Prefer to use a dedicated error indices dictionary if present
    if hasattr(self, "_error_indices") and isinstance(self._error_indices, dict):
        if coord_name in self._error_indices:
            return self._error_indices[coord_name]
        else:
            raise ValueError(f"No error indices stored for coordinate '{coord_name}'.")
    # Fallback to look for an attribute named like '_<coord_name>_err_indices'
    attr_name = f"_{coord_name}_err_indices"
    if hasattr(self, attr_name):
        return getattr(self, attr_name)
    # If neither is found, raise an informative error
    raise AttributeError(f"Error indices for coordinate '{coord_name}' not found.")

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Compute bin widths
    try:
        widths = edges[1:] - edges[:-1]
    except TypeError:
        widths = [edges[i+1] - edges[i] for i in range(len(edges)-1)]
    # Compute weighted sum
    return sum(b * w for b, w in zip(bins, widths))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences
    if isinstance(seq, Source):
        return False
    # Directly a FillRequest element
    if isinstance(seq, FillRequest):
        return True
    # Try to iterate over seq
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        return False
    return False

