def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generates a partial observer schema dictionary from a Kubernetes manifest dictionary.
    For non-list and non-dict scalar values, substitutes None. For top-level dictionaries
    (first_level=True), preserves values of key identifying fields.
    """
    # Define identifying fields that should be preserved at the top-level
    identifying_fields = {"apiVersion", "kind"}

    # Initialize the resulting schema dictionary
    schema_dict = {}

    # Preserve the identifying fields at the top-level, if requested
    if first_level:
        for field in identifying_fields:
            if field in manifest_dict:
                schema_dict[field] = manifest_dict[field]

    # Iterate over all keys in the manifest dictionary
    for key, value in manifest_dict.items():
        # Skip already handled identifying fields when tracing top-level logic
        if first_level and key in identifying_fields:
            continue

        if isinstance(value, dict):
            # Recurse for nested dictionaries
            schema_dict[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Delegate list handling to the appropriate helper function
            # (Assumes generate_default_observer_schema_list exists in the same module)
            schema_dict[key] = generate_default_observer_schema_list(value, first_level=False)
        else:
            # Replace scalar values with None, unless it's a top-level identifying field
            if not (first_level and key in identifying_fields):
                schema_dict[key] = None

    return schema_dict

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    from pathlib import Path
    import json

    p = Path(path).expanduser()
    if not p.exists():
        return False

    # Locate the manifest file (could be in .ocfl/manifest.json or ocfl-manifest.json)
    possible_manifests = [p / ".ocfl" / "manifest.json", p / "ocfl-manifest.json", p / "manifest.json"]
    manifest_path = next((mp for mp in possible_manifests if mp.is_file()), None)
    if not manifest_path:
        return False

    try:
        with manifest_path.open(encoding="utf-8") as f:
            manifest = json.load(f)
    except Exception:
        return False

    # Basic required keys in manifest
    required_keys = {"object", "version", "files"}
    if not required_keys.issubset(manifest):
        return False

    # The content directory should exist
    content_dir = p / "content"
    if not content_dir.is_dir():
        return False

    # Validate each file referenced in the manifest
    for entry in manifest.get("files", []):
        if not isinstance(entry, dict):
            return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = None
    # Try to retrieve a status attribute if it exists
    if hasattr(self, 'status'):
        status = self.status
    elif hasattr(self, 'validator_status'):
        status = self.validator_status
    elif hasattr(self, 'is_valid'):
        status = 'valid' if self.is_valid else 'invalid'
    # If a status method property exists
    elif hasattr(self, 'status_str') and callable(getattr(self, 'status_str')):
        try:
            status = self.status_str()
        except Exception:
            status = 'unknown'
    # Fallback if nothing found
    if status is None:
        status = 'unknown'
    # Convert any non-string status to string
    if not isinstance(status, str):
        status = str(status)
    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Retrieve the log collection; fall back to an empty list if not present.
    log = getattr(self, 'validation_log', getattr(self, 'log', getattr(self, 'messages', [])))
    if not log:
        return f"{prefix}No validation log."
    lines = []
    for entry in log:
        # Handle different entry types (string, tuple/list, dict)
        if isinstance(entry, (list, tuple)):
            # Prefer first element as status or category
            if len(entry) == 2:
                status, msg = entry[0], entry[1]
                lines.append(f"{prefix}{status}: {msg}")
            else:
                lines.append(prefix + " ".join(str(e) for e in entry))
        elif isinstance(entry, dict):
            # Use key-value pairs from dict
            parts = [f"{k}: {v}" for k, v in entry.items()]
            lines.append(prefix + " | ".join(parts))
        else:
            # Assume plain string
            lines.append(prefix + str(entry))
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        errors = []

        # inventory must be a dict
        if inventory is None:
            errors.append("inventory is None")
        elif not isinstance(inventory, dict):
            errors.append(f"inventory should be a dict, got {type(inventory).__name__}")

        # determine spec_version
        spec_version = getattr(self, "spec_version", None)
        if extract_spec_version:
            for comp, items in inventory.items() if isinstance(inventory, dict) else []:
                if isinstance(items, list):
                    for item in items:
                        t = item.get("type")
                        if isinstance(t, str) and t.startswith("spec_v"):
                            try:
                                spec_version = float(t.split("spec_v")[1])
                                break
                            except (ValueError, IndexError):
                                pass
                    if spec_version is not None:
                        break
        # if not found, spec_version stays as self.spec_version

        seen_ids = set()
        for comp, items in inventory.items() if isinstance(inventory, dict) else []:
            if not isinstance(items, list):
                errors.append(f"Component '{comp}' should map to a list, got {type(items).__name__}")
                continue
            for idx, item in enumerate(items):
                if not isinstance(item, dict):
                    errors.append(f"Item {idx} in component '{comp}' is not a dict")
                    continue
                # required keys
                for key in ("id", "type", "path"):
                    if key not in item:
                        errors.append(f"Item {idx} in component '{comp}' missing required key '{key}'")
                # id uniqueness
                if "id" in item:
                    if item["id"] in seen_ids:
                        errors.append(f"Duplicate id '{item['id']}' found in component '{comp}'")
                    else:
                        seen_ids.add(item["id"])
                # basic type validation
                if "type" in item and not isinstance(item["type"], str):
                    errors.append(f"Type of item {idx} in component '{comp}' is not a string")

        if errors:
            raise ValueError("Validation errors: " + "; ".join(errors))
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure digests_used is a set or iterable of digest strings
    if not isinstance(digests_used, (set, list, tuple)):
        digests_used = set(digests_used)
    # Ensure manifest_files is a dict-like structure with digest keys
    if not hasattr(manifest_files, "keys"):
        raise TypeError("manifest_files must be a dict-like object mapping digests to data")

    # Find any digests that are required but missing from the manifest
    missing = [d for d in digests_used if d not in manifest_files]
    if missing:
        msg = f"Missing digests in manifest: {', '.join(missing)}"
        if hasattr(self, "logger") and self.logger:
            self.logger.error(msg)
        raise ValueError(msg)

    # Optionally warn about digests present in the manifest but not used
    unused = [d for d in manifest_files if d not in digests_used]
    if unused and hasattr(self, "logger") and self.logger:
        self.logger.warning(f"Digest(s) in manifest not used: {', '.join(unused)}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure the block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")

    # Single file case: expect 'file', 'checksum', and 'algorithm' keys
    if 'file' in fixity:
        file_path = fixity['file']
        if file_path not in manifest_files:
            raise ValueError(f"File referenced in fixity block not present in manifest: {file_path}")
        for req_key in ('checksum', 'algorithm'):
            if req_key not in fixity:
                raise ValueError(f"Fixity block missing required '{req_key}' key.")
        return True

    # Multi-file case: expect 'files', 'checksum', and 'algorithm' keys
    if 'files' in fixity:
        if not isinstance(fixity['files'], (list, set, tuple)):
            raise ValueError("The 'files' field must be an iterable of file paths.")
        missing = [f for f in fixity['files'] if f not in manifest_files]
        if missing:
            raise ValueError(f"Files referenced in fixity block not present in manifest: {missing}")
        for req_key in ('checksum', 'algorithm'):
            if req_key not in fixity:
                raise ValueError(f"Fixity block missing required '{req_key}' key.")
        return True

    raise ValueError("Fixity block must contain either 'file' or 'files' key.")

