def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        Each node is left-aligned according to its depth in the tree.
        If `debug` is True, the representation includes the full repr of each node.
        Assumes that a node may provide a `children()` method that returns an iterable
        of child nodes, or otherwise it falls back to inspecting its `__dict__`.
        """
        def _format(node, level):
            ind = '    ' * level
            # Basic description of the node
            if debug:
                desc = f"{node.__class__.__name__} ({repr(node)})"
            else:
                desc = node.__class__.__name__
            lines = [f"{ind}{desc}"]
            # Preferred child traversal
            children_iter = None
            if hasattr(node, "children") and callable(getattr(node, "children")):
                try:
                    children_iter = node.children()
                except Exception:
                    children_iter = None
            # If children() not available, fallback to attributes
            if children_iter is not None:
                for child in children_iter:
                    lines.append(_format(child, level + 1))
            else:
                for attr, val in getattr(node, "__dict__", {}).items():
                    if attr.startswith('_'):          # Skip private/internal attrs
                        continue
                    if isinstance(val, (list, tuple)):
                        lines.append(f"{ind}    {attr}:")
                        for item in val:
                            lines.append(_format(item, level + 2))
                    else:
                        lines.append(f"{ind}    {attr}: {val}")
            return '\n'.join(lines)

        return _format(self, indent)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        return namefunc
    def _wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        # In Python 3 `result` will be a unicode string. Convert it to a byte
        # string that matches the behaviour of Python 2's tzname() API.
        if isinstance(result, str):
            # Most tzname values are ASCII, but fall back to UTF‑8 if needed.
            return result.encode('utf-8', 'ignore')
        return result
    return _wrapper }

