def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        return ''
    # Ensure each piece is a string and strip trailing whitespace
    processed = [str(p).strip() for p in pieces]
    if style == 'markdown':
        # In Markdown, separate paragraphs with blank lines
        return '\n\n'.join(processed)
    if style == 'html':
        # Wrap each piece in paragraph tags
        return '\n'.join(f'<p>{p}</p>' for p in processed)
    if style == 'plain':
        # Plain text: one line per piece
        return '\n'.join(processed)
    # Fallback: try to produce a simple representation
    try:
        return str(processed)
    except Exception:
        return ''.join(processed)

