def size_to_bytes(size: str) -> int:
    if not isinstance(size, str):
        raise ValueError("size must be a string")
    s = size.strip().upper()
    if not s:
        raise ValueError("size must not be empty")
    # Remove a trailing 'B' if present (e.g., 'KB', 'MB')
    if s.endswith("B"):
        s = s[:-1]
    # Identify the unit character if present
    unit = s[-1] if s and s[-1].isalpha() else ""
    num_part = s[:-1] if unit else s
    try:
        num = float(num_part)
    except ValueError:
        raise ValueError(f"invalid numeric part: '{num_part}'")
    # Multipliers for decimal units
    multipliers = {
        "": 1,
        "K": 1000,
        "M": 1000**2,
        "G": 1000**3,
        "T": 1000**4,
        "P": 1000**5,
        "E": 1000**6,
    }
    factor = multipliers.get(unit)
    if factor is None:
        raise ValueError(f"invalid unit: '{unit}'")
    return int(num * factor)

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    import re
    # Replace placeholders of the form <key> or {key} with values from url_args
    pattern = re.compile(r'<(?P<k1>\w+)>|{(?P<k2>\w+)}')
    def repl(m):
        key = m.group('k1') or m.group('k2')
        if key not in url_args:
            raise KeyError(f"URL placeholder {key!r} not provided")
        return str(url_args[key])
    return pattern.sub(repl, url)

