def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or str(frequency).strip().lower() == "always":
        return None

    parts = str(frequency).strip().lower().split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency!r}")

    number_str, unit = parts
    try:
        value = int(number_str)
    except ValueError:
        raise ValueError(f"Frequency number must be an integer: {number_str!r}")

    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=value)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=value)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=value)
    if unit in ("day", "days"):
        return datetime.timedelta(days=value)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=value)
    if unit in ("month", "months"):
        return datetime.timedelta(days=30 * value)
    if unit in ("year", "years"):
        return datetime.timedelta(days=365 * value)

    raise ValueError(f"Unsupported time unit in frequency: {unit!r}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        host = host.strip()
    except Exception:
        return False
    if not host:
        return False

    # Common localhost identifiers
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1":
        return True
    if host == "::1":
        return True

    # Resolve the provided host to IP addresses
    try:
        host_ips = {addr[4][0] for addr in socket.getaddrinfo(host, None)}
    except socket.gaierror:
        return False

    # Resolve the local machine to IP addresses
    try:
        local_hostname = socket.gethostname()
    except Exception:
        local_hostname = None

    local_ips = set()
    if local_hostname:
        try:
            local_ips.update({addr[4][0] for addr in socket.getaddrinfo(local_hostname, None)})
        except socket.gaierror:
            pass

    # If any of the resolved host IPs match any local IP, consider it local
    if host_ips & local_ips:
        return True

    # Finally, check if the host string matches the local hostname (case-insensitive)
    if local_hostname and host.lower() == local_hostname.lower():
        return True

    return False

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and optional default from the matcher
    if isinstance(matcher, (tuple, list)):
        if len(matcher) == 0:
            raise ValueError("Matcher tuple/list must contain at least the variable name.")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, dict):
        # Expecting keys 'name' and optional 'default'
        if 'name' not in matcher:
            raise ValueError("Matcher dict must contain a 'name' key.")
        name = matcher['name']
        default = matcher.get('default')
    elif isinstance(matcher, str):
        # Optional default after a colon
        if ':' in matcher:
            name, default = matcher.split(':', 1)
        else:
            name, default = matcher, None
    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher).__name__}")

    # Strip whitespace
    name = name.strip()
    if default is not None:
        default = default.strip()

    # Get the value from the environment
    value = os.environ.get(name)

    if value is not None:
        return value
    if default is not None:
        return default

    raise ValueError(f"Environment variable '{name}' not found and no default provided.")

