def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import logging
    import json
    import sys

    try:
        import yaml
    except ImportError:
        yaml = None

    configs = {}
    error_records = []

    logger = logging.getLogger('config_loader')

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as fh:
                if filename.lower().endswith(('.yaml', '.yml')):
                    if yaml is None:
                        raise ImportError("PyYAML is required for YAML configuration files")
                    data = yaml.safe_load(fh)
                else:
                    data = json.load(fh)
        except Exception as exc:
            exc_info = sys.exc_info()
            record = logger.makeRecord(
                name='config_loader',
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg=f"Failed to load configuration {filename}: {exc}",
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)
            continue

        if resolve_env and isinstance(data, (dict, list, str)):
            def _resolve_env(obj):
                if isinstance(obj, str):
                    return os.path.expandvars(obj)
                if isinstance(obj, dict):
                    return {k: _resolve_env(v) for k, v in obj.items()}
                if isinstance(obj, list):
                    return [_resolve_env(item) for item in obj]
                return obj

            data = _resolve_env(data)

        if overrides and isinstance(data, dict):
            for key, value in overrides.items():
                data[key] = value

        configs[filename] = data

    return configs, error_records

