        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        bookmarks = []
        for v in values:
            # If a Bookmark class with a from_raw method is available, use it.
            if hasattr(cls, "Bookmark") and hasattr(cls.Bookmark, "from_raw"):
                try:
                    bookmarks.append(cls.Bookmark.from_raw(v))
