            # Fall back to storing the raw string.
            bookmarks.append(v)
        return cls(bookmarks)

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram)."""
        # Helper: compute the raw integral of the histogram
        def _compute_raw_scale():
            if hasattr(self, "_counts"):
                return sum(self._counts)
            if hasattr(self, "data"):
                try:
                    return sum(self.data)
                except Exception:
                    pass
            # Fallback: iterate over an iterable of bin contents if available
            if hasattr(self, "bins"):
                try:
                    return sum(self.bins)
                except Exception:
                    pass
            raise lena.LenaValueError("Cannot compute scale: no bin data available")

        # Case: return the current scale
        if other is None:
            # Recompute if requested or if we haven't stored a scale yet
            if recompute or not hasattr(self, "_scale") or self._scale is None:
                self._scale = _compute_raw_scale()
            return self._scale

        # Case: rescale the histogram to a new floating-point scale
        new_scale = float(other)
        if new_scale == 0:
            raise lena.LenaValueError("Cannot rescale a histogram to a zero scale")

        current_scale = self.scale(recompute=False)
        if current_scale == 0:
            raise lena.LenaValueError("Cannot rescale a histogram with zero current scale")

        factor = new_scale / current_scale

        # Try to rescale all numerical attributes that might hold bin contents
        for attr_name in ("_counts", "data", "bins", "values"):
            if hasattr(self, attr_name):
                attr = getattr(self, attr_name)
                try:
                    # Support lists or any iterable of numbers
                    scaled = [x * factor if hasattr(x, "__iter__") else x * factor for x in attr]
                    setattr(self, attr_name, scaled)
                except Exception:
                    # Skip attributes that cannot be multiplied element-wise
                    pass

        # Update stored scale
        self._scale = new_scale
        return self._scale

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    del self[key]
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self._data:
        raise KeyError('popitem(): empty')
    key, value = self._data.popitem(last=False)
    return key, value

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('popitem from an empty dict')
    import random
    key = random.choice(list(self))
    value = self.pop(key)
    return (key, value)

