def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Diaspora request.

    The function checks for a public message first, then a private message, and finally looks for
    legacy payload markers in the request data or headers.  The returned value is True if any of
    these checks succeed, otherwise False.
    """
    # 1. Check for a public message indicator.
    #    Many request objects expose a `public_message` attribute or key; adjust as needed.
    public_msg = None
    if hasattr(request, "public_message"):
        public_msg = getattr(request, "public_message")
    elif isinstance(request, dict):
        public_msg = request.get("public_message")

    if public_msg:
        return True

    # 2. Check for a private message indicator.
    private_msg = None
    if hasattr(request, "private_message"):
        private_msg = getattr(request, "private_message")
    elif isinstance(request, dict):
        private_msg = request.get("private_message")

    if private_msg:
        return True

    # 3. Check for legacy payload markers in the payload or headers.
    legacy_markers = [
        "diaspora_legacy",
        "legacy_payload",
        "legacy",
    ]

    # Check in request data payload
    data = None
    if hasattr(request, "data"):
        data = getattr(request, "data")
    elif isinstance(request, dict):
        data = request.get("data")

    if isinstance(data, dict):
        for marker in legacy_markers:
            if marker in data or marker in data.get("metadata", {}):
                return True

    # Check in headers
    headers = None
    if hasattr(request, "headers"):
        headers = getattr(request, "headers")
    elif isinstance(request, dict):
        headers = request.get("headers")

    if isinstance(headers, dict):
        for marker in legacy_markers:
            if marker in headers:
                return True

    # If all checks fail, this is not a Diaspora request.
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Check if the request path follows the Matrix API convention
    path = getattr(request, "path", "")
    if isinstance(path, str) and path.startswith("/_matrix"):
        return True

    # Check common Matrix request headers that may indicate the request origin
    headers = getattr(request, "headers", {})
    if isinstance(headers, dict):
        if headers.get("X-Matrix-Request", "").lower() == "true":
            return True
        if "content-type" in headers:
            if "application/json" in headers["content-type"]:
                # Matrix requests tend to be JSON, but this alone is not sufficient
                pass
    return False

