def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json, xml.etree.ElementTree as ET

    result = {"subject": None, "aliases": [], "links": []}

    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            result["subject"] = data.get("subject") or data.get("subject")
            result["aliases"] = data.get("aliases", [])
            for link in data.get("links", []):
                href = link.get("href")
                if href:  # only include if href exists
                    result["links"].append({
                        "rel": link.get("rel"),
                        "href": href,
                        "type": link.get("type")
                    })
            return result
    except json.JSONDecodeError:
        pass

    # Fall back to XRD (XML)
    try:
        root = ET.fromstring(document)
        # Resolve namespace if present
        ns_tag = root.tag[root.tag.find("{"):root.tag.find("}") + 1] if "}" in root.tag else ""
        for child in root:
            tag = child.tag.replace(ns_tag, "")
            if tag == "Subject":
                result["subject"] = child.text.strip() if child.text else None
            elif tag == "Alias":
                if child.text:
                    result["aliases"].append(child.text.strip())
            elif tag == "Link":
                href = child.attrib.get("href")
                if href:
                    result["links"].append({
                        "rel": child.attrib.get("rel"),
                        "href": href,
                        "type": child.attrib.get("type")
                    })
        return result
    except ET.ParseError:
        pass

    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        username, domain = handle.split('@', 1)
        # RFC7033 requires the resource to be URL‑encoded
        import urllib.parse
        resource = urllib.parse.quote(f'acct:{handle}', safe='')
        url = f'https://{domain}/.well-known/webfinger?resource={resource}'
        import urllib.request
        req = urllib.request.Request(
            url,
            headers={
                'Accept': 'application/jrd+json, application/json',
                'User-Agent': 'webfinger-client/1.0',
            },
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status == 200:
                # Determine charset; default to utf-8 if unknown
                charset = resp.headers.get_content_charset('utf-8')
                return resp.read().decode(charset)
    except Exception:
        # Any network or parsing issue results in None, no exception raised
        return None
    return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json
    from urllib.error import URLError, HTTPError

    if not handle:
        raise ValueError("handle must be provided")

    # Ensure handle is in the form local_user@domain
    if handle.startswith("acct:"):
        # The caller may have already provided the acct URI
        acct_uri = handle
        try:
            local_part, domain = handle.split("acct:", 1)[1].split("@", 1)
        except ValueError:
            raise ValueError("handle must contain '@' after optional 'acct:' prefix")
    else:
        acct_uri = f"acct:{handle}"
        try:
            local_part, domain = handle.split("@", 1)
        except ValueError:
            raise ValueError("handle must be of the form local_user@domain")

    # Construct the webfinger URL
    query = urllib.parse.urlencode({"resource": acct_uri})
    url = f"https://{domain}/.well-known/webfinger?{query}"

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                raise RuntimeError(f"HTTP error {response.status} while fetching webfinger")
            raw_data = response.read().decode("utf-8")
    except HTTPError as err:
        raise RuntimeError(f"HTTPError while fetching webfinger: {err.code} {err.reason}") from err
    except URLError as err:
        raise RuntimeError(f"URLError while fetching webfinger: {err.reason}") from err

    try:
        data = json.loads(raw_data)
    except json.JSONDecodeError as err:
        raise ValueError(f"Failed to parse JSON from webfinger: {err.msg}") from err

    return data

