@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
            is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("Spec content is missing")

        # Load YAML if provided as a string, otherwise assume dict
        if isinstance(spec_content, str):
            try:
                spec = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Error parsing YAML spec: {exc}") from exc
        else:
            spec = spec_content

        if not isinstance(spec, dict):
            raise IRValidatorException(f"Spec should be a mapping, got {type(spec).__name__}")

        # Ensure required fields are present
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in spec]
        if missing:
            raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")

        return spec

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if not yaml_file:
            raise IRValidatorException("No YAML file specified.")
        try:
            with open(yaml_file, "r") as fh:
                data = yaml.safe_load(fh)
        except FileNotFoundError as exc:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from exc
        except yaml.YAMLError as exc:
            raise IRValidatorException(f"Error parsing YAML file: {exc}") from exc

        if data is None:
            data = {}

        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [key for key in required_fields if key not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dict")

    # If there's no include directive, just return the original dict
    if "include" not in parser_dict:
        return parser_dict

    # Extract and remove the include directive
    include = parser_dict.pop("include")

    # Normalise the include structure to a list of dictionaries
    if isinstance(include, dict):
        include_items = [include]
    elif isinstance(include, (list, tuple)):
        include_items = include
    else:
        # If include is a single key, wrap it in a dict for processing
        include_items = [{include: None}]

    # Resolve each include entry
    for inc in include_items:
        # An include entry can be a dict mapping group names to data
        if isinstance(inc, dict):
            for key, val in inc.items():
                if val is None:
                    continue
                # If the value is a dictionary, merge recursively
                if isinstance(val, dict):
                    # Ensure the target key exists as a dict
                    target = parser_dict.setdefault(key, {})
                    if not isinstance(target, dict):
                        # Cannot merge a non-dict; replace it
                        target = {}
                        parser_dict[key] = target
                    # Recursively resolve includes in the included data
                    target.update(self._include_groups(val))
                else:
                    # For non-dict values, just set/overwrite
                    parser_dict[key] = val
        else:
            # An include entry is a single key referencing a group
            # Attempt to load this group from the environment/registry
            group_data = getattr(self, "_group_registry", {}).get(inc)
            if group_data is not None:
                parser_dict.update(self._include_groups(group_data))
            else:
                # If the group is not found, raise an error
                raise KeyError(f"Included group '{inc}' not found in registry")

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, "spec", None)
    if spec is None:
        return defaults

    # The spec might expose arguments as .arguments or .args
    args_container = getattr(spec, "arguments", getattr(spec, "args", None))
    if args_container is None:
        return defaults

    # Try to iterate over dictionary items; fall back to a plain iterable
    try:
        items = args_container.items()
    except AttributeError:
        items = args_container

    for key, value in items:
        # If an argument is defined as a mapping, pull 'default' if present
        if isinstance(value, dict):
            if "default" in value:
                defaults[key] = value["default"]
        else:
            # If the value itself is the default
            defaults[key] = value

    return defaults

