def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Ensure the commands registry exists
    if not hasattr(self, 'commands') or not isinstance(self.commands, dict):
        raise AttributeError("The object does not have a 'commands' dictionary attribute.")
    # Retrieve the command object
    cmd = self.commands.get(command_name)
    if cmd is None:
        raise KeyError(f"Command '{command_name}' not found.")
    # Try to fetch the option spec from common patterns
    if hasattr(cmd, 'options') and isinstance(cmd.options, dict):
        opt_spec = cmd.options.get(argument_name)
        if opt_spec is None:
            raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'.")
        return opt_spec
    if hasattr(cmd, 'get_option'):
        try:
            return cmd.get_option(argument_name)
        except Exception as exc:
            raise KeyError(f"Failed to get option '{argument_name}' for command '{command_name}': {exc}") from exc
    raise AttributeError(f"Command object for '{command_name}' does not provide a way to access options.")

def get_silent_args(self, args):
