def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    Return a list of option names that have a satisfied ``required_when`` condition.

    :param command_name: str, the name of the command.
    :param options_spec: list of option specification dictionaries.
    :param args: dict of parsed arguments (name -> value).
    :return: list of option names that become required by their ``required_when`` condition.
    """
    required = []

    for opt in options_spec:
        cond = opt.get("required_when")
        if cond is None:
            continue

        # Determine if condition is satisfied.
        satisfied = False

        # Callable condition.
        if callable(cond):
            try:
                satisfied = cond(args, command_name)
            except TypeError:
                # Some callables expect only args.
                try:
                    satisfied = cond(args)
                except Exception:
                    satisfied = False

        # String condition -> treat as key in args that must be truthy.
        elif isinstance(cond, str):
            if cond in args:
                val = args[cond]
                satisfied = bool(val)

        # Iterable of conditions -> any True satisfies.
        elif isinstance(cond, (list, tuple)):
            for sub in cond:
                if isinstance(sub, str):
                    if sub in args and bool(args[sub]):
                        satisfied = True
                        break
                elif callable(sub):
                    try:
                        if sub(args, command_name):
                            satisfied = True
                            break
                    except TypeError:
                        if sub(args):
                            satisfied = True
                            break

        # Dict mapping command names to conditions or default.
        elif isinstance(cond, dict):
            # Get condition for current command or default if specified.
            conditioned = None
            if command_name in cond:
                conditioned = cond[command_name]
            elif "default" in cond:
                conditioned = cond["default"]

            if conditioned is not None:
                if isinstance(conditioned, str):
                    if conditioned in args and bool(args[conditioned]):
                        satisfied = True
                elif isinstance(conditioned, bool):
                    satisfied = conditioned
                elif callable(conditioned):
                    try:
                        satisfied = conditioned(args, command_name)
                    except TypeError:
                        try:
                            satisfied = conditioned(args)
                        except Exception:
                            satisfied = False

        # If evaluated to True, add name.
        if satisfied:
            name = opt.get("name")
            if name:
                required.append(name)

    return required

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        # Iterate over each argument in the provided dictionary.
        for arg_name, arg_value in args.items():
            # Determine the maximum length for this argument.
            max_len = getattr(self, f"{arg_name}_max_length", None)
            if max_len is None:
                # If no length constraint is defined, skip this argument.
                continue

            # Ensure the value is a string before checking its length.
            if isinstance(arg_value, str):
                if len(arg_value) > max_len:
                    raise ValueError(
                        f"Argument '{arg_name}' is too long: "
                        f"maximum allowed is {max_len} characters."
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # the mapping of argument names to their allowed choices
    choices_map = getattr(self, "choices", {})
    for name, allowed in choices_map.items():
        if name not in args:
            continue
        value = args[name]
        # Handle iterable values (e.g., list/tuple/set)
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{name}'. Allowed choices: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{name}'. Allowed choices: {allowed}"
                )

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Extract optional global min/max limits
    min_val = args.get('min')
    max_val = args.get('max')

    # If no bounds are provided, nothing to validate
    if min_val is None or max_val is None:
        return

    # Validate each argument against the bounds, skipping the min/max keys themselves
    for name, value in args.items():
        if name in ('min', 'max'):
            continue
        try:
            if value < min_val or value > max_val:
                raise ValueError(
                    f"Argument '{name}' with value {value} is out of bounds "
                    f"({min_val} <= value <= {max_val})"
                )
        except TypeError as exc:
            # The value is not comparable to the bounds (e.g., a string)
            raise TypeError(
                f"Argument '{name}' with value {value} cannot be compared to bounds "
                f"({min_val} <= value <= {max_val})"
            ) from exc
    # If all arguments are within bounds, simply return None (no exception raised)

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    # If the caller passed a dict, just update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # Prepare a new dictionary to hold parsed values
    new_vars = {}

    # Helper to attempt JSON parsing for values
    def _parse_value(val):
        try:
            import json
            return json.loads(val)
        except Exception:
            return val

    # Handle iterable types: list, tuple, set
    if isinstance(extra_vars, (list, tuple, set)):
        for item in extra_vars:
            # Items can be dict, tuple/list of length 2, or a string
            if isinstance(item, dict):
                new_vars.update(item)
            elif isinstance(item, (tuple, list)) and len(item) == 2:
                key, value = item
                new_vars[key] = _parse_value(str(value))
            elif isinstance(item, str):
                # Parse key=value strings, strip whitespace
                if '=' in item:
                    key, _, value = item.partition('=')
                    key = key.strip()
                    value = value.strip()
                    if key:
                        new_vars[key] = _parse_value(value)
            else:
                # Skip unsupported types
                continue
    else:
        # Fallback: try to cast to dict
        try:
            new_vars.update(dict(extra_vars))
        except Exception:
            pass

    vars_dict.update(new_vars)
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts string arguments to their appropriate native types.
        Works recursively for comma‑separated lists.

        :param parser_name: The command name (currently unused).
        :param values_dict: The dictionary of arguments as strings.
        """
        bool_vals = {'true': True, 'false': False}
        def _convert(val):
            if isinstance(val, str):
                s = val.strip()
                # boolean
                lower = s.lower()
                if lower in bool_vals:
                    return bool_vals[lower]
                # integer
                try:
                    return int(s)
                except Exception:
                    pass
                # float
                try:
                    return float(s)
                except Exception:
                    pass
                # list
                if ',' in s:
                    parts = [x.strip() for x in s.split(',')]
                    return [_convert(x) for x in parts]
            return val

        for key, value in values_dict.items():
            values_dict[key] = _convert(value)

        # Return is optional – the dict is modified in place
        return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

