    """
    import os, json
    # Look for common spec filenames
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml", "spec.json", "spec.yaml", "spec.yml"):
        spec_path = os.path.join(plugin_dir, fname)
        if os.path.isfile(spec_path):
            break
    else:
        return {}
    # Load spec (YAML if available, otherwise JSON)
    if spec_path.lower().endswith((".yaml", ".yml")):
        try:
            import yaml
            with open(spec_path, "r", encoding="utf-8") as f:
                spec = yaml.safe_load(f)
        except Exception:
            return {}
    else:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec = json.load(f)
    # Flatten a nested dictionary
    flat = {}
    def _flatten(d, parent_key=""):
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key)
            else:
                flat[new_key] = v
    if isinstance(spec, dict):
        _flatten(spec)
    return flat

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    from pathlib import Path
    root = Path(root).resolve()
    path = Path(path).resolve()
    try:
        rel_path = path.relative_to(root)
    except ValueError:
        raise ValueError(f"Path '{path}' is not under root '{root}'.")
    return str(rel_path)
